// --------------------------------------------------
// DATA HAZARD (RAW: Read After Write)
// --------------------------------------------------
I1: ADD R1, R2, R3  // R1 Written in WB (C5)
I2: SUB R4, R1, R5  // R1 Needed in ID (C2)

// Pipeline Timeline (Stall/Interlock Required)
// C1: I1(IF)
// C2: I1(ID), I2(IF)
// C3: I1(EX), I2(STALL)
// C4: I1(MEM), I2(STALL)
// C5: I1(WB), I2(ID)

// Mitigation: Data Forwarding/Bypassing
// Result of I1 EX or MEM stage is piped
// directly to I2 EX stage input.


// --------------------------------------------------
// STRUCTURAL HAZARD (Resource Conflict)
// --------------------------------------------------
// Single-ported Memory Unit (MEM)
I1: LW R1, 0(R2)
I2: SW R3, 4(R4)
I3: LW R5, 8(R6)

// C4: I1 (MEM), I2 (EX), I3 (ID)
// C5: I1 (WB), I2 (MEM), I3 (EX)
// C6: I2 (WB), I3 (MEM)

// Conflict occurs if I1(MEM) and I3(IF) need the
// same physical memory port simultaneously.
// Solution: Duplicate the conflicted hardware unit
// (e.g., Separate Instruction/Data Caches).


// --------------------------------------------------
// CONTROL HAZARD (Branch Delay)
// --------------------------------------------------
I_B: BEQ R1, R2, Target // Resolved in EX Stage (C3)

I_F1: Next sequential instruction (Fetched C2)
I_F2: Next sequential instruction (Fetched C3)

// Assumption: Not Taken prediction fails
// Pipeline must flush I_F1 and I_F2.
// Penalty: (Pipeline depth - BRS stage index)
// Mitigations: Branch Prediction, Delayed Slot
//             (Executing useful instruction after I_B)
